CREATE OR REPLACE FUNCTION public.add_mail_suppression(p_email text, p_reason text, p_note text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_email text := lower(btrim(coalesce(p_email, '')));
  v_id uuid;
begin
  perform app_private.require_mail_admin('add_mail_suppression');
  if v_email !~ '^[a-z0-9._%+-]+@[a-z0-9-]+(\.[a-z0-9-]+)+$' or char_length(v_email) > 254 then raise exception 'add_mail_suppression: e-posta' using errcode = '22023'; end if;
  if p_reason not in ('manual', 'bounced', 'complaint') then raise exception 'add_mail_suppression: neden' using errcode = '22023'; end if;
  insert into public.mail_suppressions (email, reason, note, created_by) values (v_email, p_reason, nullif(btrim(left(coalesce(p_note, ''), 300)), ''), auth.uid())
  on conflict (email) do nothing returning id into v_id;
  if v_id is null then select id into v_id from public.mail_suppressions where email = v_email; end if;
  return v_id;
end $function$

CREATE OR REPLACE FUNCTION public.aggregate_analytics_day(p_day date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_heat integer;
  v_scroll integer;
begin
  if not app_private.is_trusted_context() and not app_private.has_role('super_admin', 'admin') then
    raise exception 'aggregate_analytics_day: yetki yok' using errcode = '42501';
  end if;
  delete from public.heatmap_aggregates where day = p_day;
  insert into public.heatmap_aggregates (path, device, day, kind, bucket_x, bucket_y, hits)
  select e.path, e.device, p_day, e.type, least(floor(e.x_pct)::int, 99), floor(e.y_pct)::int, count(*)
    from public.analytics_events e
   where e.occurred_at >= p_day and e.occurred_at < p_day + 1
     and e.type in ('click','rage_click','dead_click','attention') and e.x_pct is not null and e.y_pct is not null
   group by e.path, e.device, e.type, least(floor(e.x_pct)::int, 99), floor(e.y_pct)::int;
  get diagnostics v_heat = row_count;

  delete from public.scroll_depth_aggregates where day = p_day;
  insert into public.scroll_depth_aggregates (path, device, day, views, reached_25, reached_50, reached_75, reached_100)
  select pv.path, s.device, p_day, count(*),
         count(*) filter (where pv.max_scroll_pct >= 25), count(*) filter (where pv.max_scroll_pct >= 50),
         count(*) filter (where pv.max_scroll_pct >= 75), count(*) filter (where pv.max_scroll_pct >= 100)
    from public.analytics_pageviews pv join public.analytics_sessions s on s.id = pv.session_id
   where pv.viewed_at >= p_day and pv.viewed_at < p_day + 1
   group by pv.path, s.device;
  get diagnostics v_scroll = row_count;
  return jsonb_build_object('heatmap_rows', v_heat, 'scroll_rows', v_scroll);
end $function$

CREATE OR REPLACE FUNCTION public.claim_my_leads()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := auth.uid(); v_email text; v_n integer;
begin
  if v_uid is null then return 0; end if;
  select lower(u.email) into v_email from auth.users u where u.id = v_uid and u.email_confirmed_at is not null;
  if v_email is null then return 0; end if;
  update public.leads set user_id = v_uid where user_id is null and lower(email) = v_email;
  get diagnostics v_n = row_count;
  return v_n;
end $function$

CREATE OR REPLACE FUNCTION public.create_customer_from_lead(p_lead_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_lead public.leads%rowtype;
  v_id uuid;
begin
  select * into v_lead from public.leads where id = p_lead_id;
  if not found then raise exception 'create_customer_from_lead: lead' using errcode = '22023'; end if;
  if v_lead.customer_id is not null then return v_lead.customer_id; end if;
  if v_lead.anonymized_at is not null then raise exception 'create_customer_from_lead: anonymized' using errcode = '22023'; end if;

  insert into public.customers (type, full_name, company_title, city, email, phone, contact_person, contact_phone, source, notes)
  values (case when nullif(btrim(v_lead.company), '') is null then 'individual' else 'corporate' end,
          v_lead.full_name, nullif(btrim(v_lead.company), ''), v_lead.city, v_lead.email, v_lead.phone,
          case when nullif(btrim(v_lead.company), '') is null then null else v_lead.full_name end,
          case when nullif(btrim(v_lead.company), '') is null then null else v_lead.phone end,
          'lead', 'Talep ' || v_lead.ref_no)
  returning id into v_id;
  update public.leads set customer_id = v_id where id = p_lead_id;
  return v_id;
end $function$

CREATE OR REPLACE FUNCTION public.create_sale_from_configuration(p_configuration_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_sale uuid;
  v_lead uuid;
  v_ref text;
  v_version integer;
  v_price numeric;
  v_currency text;
  v_n integer := 0;
begin
  if not app_private.has_role('super_admin', 'admin', 'sales') then raise exception 'create_sale_from_configuration: yetki yok' using errcode = '42501'; end if;
  select c.sale_id, c.lead_id, c.ref_code, c.current_version, c.estimated_price, c.currency into v_sale, v_lead, v_ref, v_version, v_price, v_currency
    from public.configurations c where c.id = p_configuration_id;
  if v_ref is null then raise exception 'create_sale_from_configuration: yok' using errcode = '22023'; end if;
  if v_sale is not null then return v_sale; end if;
  if v_lead is null then raise exception 'create_sale_from_configuration: talep yok' using errcode = '22023'; end if;
  v_sale := public.create_sale_from_lead(v_lead);
  select coalesce(max(si.sort_order), 0) into v_n from public.sale_items si where si.sale_id = v_sale;
  insert into public.sale_items (sale_id, description, quantity, unit, unit_price, line_total, sort_order)
  select v_sale,
         'Konfig ' || v_ref || ' v' || v_version::text || ' · ' || i.element_group || coalesce(' · ' || i.profile_code_snapshot, ''),
         greatest(coalesce(i.total_weight_kg, i.total_area_m2, i.total_length_m, i.piece_count::numeric), 0.001),
         case when i.total_weight_kg is not null then 'kg' when i.total_area_m2 is not null then 'm2' when i.total_length_m is not null then 'm' else 'adet' end,
         0, 0, v_n + i.sort_order
    from public.configuration_items i join public.configuration_versions v on v.id = i.configuration_version_id
   where v.configuration_id = p_configuration_id and v.version = v_version;
  update public.sales set configuration_id = p_configuration_id,
         notes = coalesce(notes, '') || E'\nKonfigürasyon ' || v_ref || ' v' || v_version::text
               || case when v_price is not null then ' · tahmini ' || v_price::text || ' ' || coalesce(v_currency, '') else '' end
   where id = v_sale;
  update public.configurations set sale_id = v_sale, status = 'converted_to_sale' where id = p_configuration_id;
  return v_sale;
end $function$

CREATE OR REPLACE FUNCTION public.create_sale_from_lead(p_lead_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_customer uuid;
  v_sale uuid;
  v_uid uuid := auth.uid();
begin
  if not (app_private.is_trusted_context() or app_private.has_role('super_admin', 'admin', 'sales')) then
    raise exception 'create_sale_from_lead: yetki yok' using errcode = '42501';
  end if;
  select s.id into v_sale from public.sales s where s.lead_id = p_lead_id and s.status <> 'cancelled' limit 1;
  if v_sale is not null then return v_sale; end if;
  v_customer := public.create_customer_from_lead(p_lead_id);
  insert into public.sales (customer_id, lead_id, assigned_to, created_by, notes)
  values (v_customer, p_lead_id, v_uid, v_uid, (select 'Talep ' || l.ref_no from public.leads l where l.id = p_lead_id))
  returning id into v_sale;
  insert into public.sale_items (sale_id, product_id, description, quantity, unit, unit_price, line_total, sort_order)
  select v_sale, li.product_id,
         li.product_name_snapshot || coalesce(' · ' || li.variant_label_snapshot, ''),
         li.quantity, coalesce(li.unit, 'adet'), 0, 0, li.sort_order
    from public.lead_items li where li.lead_id = p_lead_id;
  update public.leads set status = 'won' where id = p_lead_id and status in ('new', 'in_review', 'quoted');
  return v_sale;
end $function$

CREATE OR REPLACE FUNCTION public.customer_lead_message(p_lead_id uuid, p_kind text, p_body text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  perform app_private.require_gate();
  if auth.uid() is null then raise exception 'customer_lead_message: auth' using errcode = '42501'; end if;
  perform app_private.throttle('clm:' || auth.uid()::text, 5, interval '1 hour');
  return public.customer_lead_message_impl(p_lead_id, p_kind, p_body);
end $function$

CREATE OR REPLACE FUNCTION public.customer_lead_message_impl(p_lead_id uuid, p_kind text, p_body text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := auth.uid(); v_lead public.leads%rowtype; v_id uuid; v_to text;
begin
  if v_uid is null then raise exception 'customer_lead_message: auth' using errcode = '42501'; end if;
  if p_kind not in ('reply','revision_request','cancel_request') then raise exception 'customer_lead_message: kind' using errcode = '22023'; end if;
  if length(btrim(coalesce(p_body, ''))) < 3 or length(p_body) > 4000 then raise exception 'customer_lead_message: body' using errcode = '22023'; end if;
  select * into v_lead from public.leads l where l.id = p_lead_id and l.user_id = v_uid;
  if v_lead.id is null then raise exception 'customer_lead_message: lead' using errcode = '42501'; end if;
  insert into public.lead_replies (lead_id, author_id, subject, body, direction, kind, sent_at)
  values (p_lead_id, v_uid, case p_kind when 'revision_request' then 'Revizyon isteği' when 'cancel_request' then 'İptal isteği' else 'Müşteri mesajı' end, btrim(p_body), 'inbound', p_kind, now())
  returning id into v_id;
  insert into public.notifications (target_role, type, payload, link_path)
  values ('sales', 'lead.customer_message', jsonb_build_object('ref_no', v_lead.ref_no, 'kind', p_kind, 'lead_id', p_lead_id), '/admin/leads/' || p_lead_id::text);
  if p_kind = 'cancel_request' and v_lead.status in ('new','in_review') then update public.leads set status = 'lost', lost_reason = 'customer_cancel', updated_at = now() where id = p_lead_id; end if;
  v_to := nullif(btrim((select s.value #>> '{}' from public.site_settings s where s.key = 'contact.email')), '');
  if v_to is not null then
    insert into public.email_queue (template_key, to_email, locale, payload, priority, related_type, related_id)
    values ('lead.received.company', v_to, 'tr', jsonb_build_object('ref_no', v_lead.ref_no, 'full_name', coalesce(v_lead.full_name, ''), 'email', coalesce(v_lead.email, ''), 'phone', coalesce(v_lead.phone, ''), 'company', coalesce(v_lead.company, ''), 'service', '', 'message', '[' || p_kind || '] ' || btrim(p_body)), 3, 'lead', p_lead_id);
  end if;
  return v_id;
end $function$

CREATE OR REPLACE FUNCTION public.delete_my_account()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := auth.uid();
begin
  if v_uid is null then raise exception 'delete_my_account: auth' using errcode = '42501'; end if;
  if exists (select 1 from public.profiles p where p.id = v_uid and p.role <> 'member') then raise exception 'delete_my_account: staff' using errcode = '42501'; end if;
  update public.customers set profile_id = null where profile_id = v_uid;
  delete from auth.users where id = v_uid;
end $function$

